// Download original Figma exports. The token is read from the environment and never logged/stored.
const fs = require('fs');
const path = require('path');
const { ROOT, SNAPSHOT, read, write, inside, hash } = require('./common');
const { extractFigmaFileKey } = require('../figma/utils');
async function request(url, authenticated = false) {
  const response = await fetch(url, { headers: authenticated ? { 'X-Figma-Token': process.env.FIGMA_TOKEN } : {}, signal: AbortSignal.timeout(120000) });
  if (!response.ok) throw new Error(`FIGMA_HTTP_${response.status}; retry-after=${response.headers.get('retry-after') || 'not supplied'}`);
  return response;
}
async function main() {
  const args = process.argv.slice(2);
  const opts = Object.fromEntries(Array.from({ length: args.length / 2 }, (_, i) => [args[i * 2].replace(/^--/, ''), args[i * 2 + 1]]));
  if (!process.env.FIGMA_TOKEN) throw new Error('FIGMA_TOKEN unavailable. Use authenticated Figma MCP export/download instead; do not invent an asset.');
  if (!opts.node || !opts.output || !['png', 'svg', 'jpg'].includes(opts.format || 'png')) throw new Error('Usage: --node <id> --output <snapshot-relative-path> --format png|svg|jpg');
  const fileKey = extractFigmaFileKey(read(path.join(ROOT, 'factory/project.json')).figma.url);
  const format = opts.format || 'png';
  const url = `https://api.figma.com/v1/images/${fileKey}?ids=${encodeURIComponent(opts.node)}&format=${format}&scale=1`;
  const response = await (await request(url, true)).json();
  const source = response.images?.[opts.node];
  if (!source) throw new Error(`Figma did not export ${opts.node}: ${response.err || 'no image'}`);
  const bytes = Buffer.from(await (await request(source)).arrayBuffer());
  const target = inside(SNAPSHOT, opts.output);
  fs.mkdirSync(path.dirname(target), { recursive: true }); fs.writeFileSync(target, bytes);
  const provenance = { fileKey, nodeId: opts.node, path: opts.output, format, scale: 1, capturedAt: new Date().toISOString(), sha256: hash(bytes), transport: 'figma-rest-export' };
  write(`${target}.source.json`, provenance);
  console.log(JSON.stringify(provenance));
}
if (require.main === module) main().catch(e => { console.error(e.message); process.exitCode = 1; });
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { spawnSync } = require('child_process');

const ROOT = path.resolve(__dirname, '../../..');
const CACHE = path.join(ROOT, '.factory-cache/autopilot');
const SNAPSHOT = path.join(ROOT, '.factory-cache/figma/latest');
const read = (file) => JSON.parse(fs.readFileSync(file, 'utf8').replace(/^\uFEFF/, ''));
const hash = (value) => crypto.createHash('sha256').update(value).digest('hex');
function write(file, value) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  const temp = `${file}.${process.pid}.tmp`;
  fs.writeFileSync(temp, JSON.stringify(value, null, 2) + '\n');
  fs.renameSync(temp, file);
}
function inside(root, relative) {
  if (typeof relative !== 'string' || !relative) throw new Error('Missing artifact path');
  const file = path.resolve(root, relative);
  const rel = path.relative(root, file);
  if (rel.startsWith('..') || path.isAbsolute(rel)) throw new Error(`Artifact outside root: ${relative}`);
  return file;
}
function files(root, exclude = new Set()) {
  if (!fs.existsSync(root)) return [];
  return fs.readdirSync(root, { withFileTypes: true }).flatMap(e => {
    if (exclude.has(e.name) || e.isSymbolicLink()) return [];
    const f = path.join(root, e.name);
    return e.isDirectory() ? files(f, exclude) : [f];
  });
}
function fingerprint(root = ROOT, selection = ['src', 'assets', 'acf-json', 'functions', 'partials', 'dist', 'templates', 'woocommerce', 'scripts/factory/project']) {
  const list = selection.flatMap(p => files(path.join(root, p)));
  list.push(...fs.readdirSync(root).filter(p => p.endsWith('.php')).map(p => path.join(root, p)));
  return hash(list.sort().map(f => `${path.relative(root, f)}:${hash(fs.readFileSync(f))}`).join('\n'));
}
function engineFingerprint() {
  return hash(['scripts/factory/autopilot', 'factory/schemas'].flatMap(p => files(path.join(ROOT, p)))
    .concat([path.join(ROOT, 'factory/autopilot.json'), path.join(ROOT, 'scripts/factory/figma/validate-snapshot.js')])
    .sort().map(f => `${path.relative(ROOT, f)}:${hash(fs.readFileSync(f))}`).join('\n'));
}
function alive(pid) {
  try { process.kill(pid, 0); return true; } catch (e) { return e.code === 'EPERM'; }
}
function resolveCodex() {
  const explicit = process.env.FACTORY_CODEX_PATH;
  const command = process.platform === 'win32' ? 'where.exe' : 'which';
  const candidates = explicit ? [explicit] : ['codex.exe', 'codex'].flatMap(name => {
    const r = spawnSync(command, [name], { encoding: 'utf8', windowsHide: true });
    return r.status === 0 ? r.stdout.trim().split(/\r?\n/).filter(f => !/\.(cmd|ps1|bat)$/i.test(f)) : [];
  });
  const found = [...new Set(candidates)].filter(f => fs.existsSync(f)).map(file => {
    const r = spawnSync(file, ['--version'], { encoding: 'utf8', windowsHide: true });
    return { file, version: (r.stdout || '').match(/\d+\.\d+\.\d+/)?.[0], ok: r.status === 0 };
  }).filter(x => x.ok && x.version);
  found.sort((a, b) => b.version.localeCompare(a.version, undefined, { numeric: true }));
  if (!found.length) throw new Error('CODEX_UNAVAILABLE: set FACTORY_CODEX_PATH to a native Codex executable.');
  return found[0];
}
module.exports = { ROOT, CACHE, SNAPSHOT, read, write, hash, inside, files, fingerprint, engineFingerprint, alive, resolveCodex };
